"""Offline negative controls using copies of actual retained rank records; no jobs."""
from pathlib import Path
import argparse,ast,copy,hashlib,json
p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();source=Path(__file__).with_name('reduce_selected_pairs.py');tree=ast.parse(source.read_text());function=next(n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name=='classify_rank');scope={};exec(compile(ast.Module(body=[function],type_ignores=[]),'<rank-classifier-only>','exec'),scope);classify=scope['classify_rank']
w=a.root/'selected_existing_w_off/W7800tp2/off_1_old.run.json';v=a.root/'raw/matrix729_v_off_pair1/runs/20261020T230018/V620tp1/off_1_old.run.json';wr=json.loads(w.read_text())['ranks'];vr=json.loads(v.read_text())['ranks'];worker=next(r for r in wr if r['rank']==1);rank0=next(r for r in wr if r['rank']==0);tp1=vr[0];assert classify(worker,'W7800tp2')['classification']=='intentional_tp_worker_sigterm';assert classify(rank0,'W7800tp2')['classification']=='clean_exit_0';assert classify(tp1,'V620tp1')['classification']=='clean_exit_0';rows=[]
for label,base,updates,rig in [('worker_SIGKILL',worker,{'actual_exit_status':-9},'W7800tp2'),('worker_SIGSEGV',worker,{'actual_exit_status':-11},'W7800tp2'),('worker_not_alive_before_teardown',worker,{'alive_before_intentional_teardown':False},'W7800tp2'),('worker_unexpected_reason',worker,{'exit_reason':'unexpected earlier exit'},'W7800tp2'),('worker_forced_timeout_kill',worker,{'forced_kill_after_term_timeout':True},'W7800tp2'),('worker_group_still_present',worker,{'process_group_gone':False},'W7800tp2'),('rank0_SIGTERM',rank0,{'actual_exit_status':-15},'W7800tp2'),('TP1_SIGTERM',tp1,{'actual_exit_status':-15},'V620tp1')]:
 changed=copy.deepcopy(base);changed.update(updates)
 try:classify(changed,rig);red=False
 except AssertionError:red=True
 assert red,label;rows.append({'control':label,'mutated_fields':updates,'red':red,'scope':'Mutated copy of an actual record; not a runtime or numerical failure'})
result={'validated':True,'reducer_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'actual_record_sha256':{str(w.relative_to(a.root)):hashlib.sha256(w.read_bytes()).hexdigest(),str(v.relative_to(a.root)):hashlib.sha256(v.read_bytes()).hexdigest()},'controls':rows,'all8_red':True,'actual_baseline_worker_sigterm_accepted_only_under_explicit_intentional_conditions':True,'no_GPU_network_or_runtime_changes':True};a.output.write_text(json.dumps(result,indent=2)+'\n');print('Actual positive records accepted; eight negative controls red')
